WITH compensation_history AS (SELECT "wren_src_compensation_history".monthly_salary AS monthly_salary, "wren_src_compensation_history".effective_date AS effective_date FROM (SELECT compensation_history.effective_date, compensation_history.monthly_salary FROM (SELECT __source.effective_date AS effective_date, __source.monthly_salary AS monthly_salary FROM hr.compensation_history AS __source) AS compensation_history) AS "wren_src_compensation_history") SELECT AVG(monthly_salary) AS average_salary FROM compensation_history WHERE effective_date = CAST('2024-09-01' AS DATE)